good_example:
// Use a dedicated proxy enum that maps cleanly to the IPC domain.
use serde::{Serialize, Deserialize};
use arrow::array::{Array, Float64Array, StringArray, ArrayRef};
use std::sync::Arc;

#[derive(Serialize, Deserialize)]
pub enum IpcValue {
    Null,
    Bool(bool),
    I64(i64),
    F64(f64),
    String(String),
    F64Array(Vec<f64>),
    StringArray(Vec<String>),
}

impl From<&dyn Array> for IpcValue {
    fn from(arr: &dyn Array) -> Self {
        match arr.data_type() {
            DataType::Float64 => {
                let a = arr.as_any().downcast_ref::<Float64Array>().unwrap();
                IpcValue::F64Array((0..a.len()).map(|i| a.value(i)).collect())
            }
            DataType::Utf8 => {
                let a = arr.as_any().downcast_ref::<StringArray>().unwrap();
                IpcValue::StringArray((0..a.len()).map(|i| a.value(i).to_string()).collect())
            }
            _ => IpcValue::Null,
        }
    }
}

impl TryInto<ArrayRef> for IpcValue {
    type Error = String;
    fn try_into(self) -> Result<ArrayRef, Self::Error> {
        match self {
            IpcValue::F64Array(vals) => {
                Ok(Arc::new(Float64Array::from(vals)))
            }
            IpcValue::StringArray(vals) => {
                Ok(Arc::new(StringArray::from(vals)))
            }
            _ => Err(format!("unsupported conversion"))
        }
    }
}
